@@ -25,3 +25,17 @@
   .pdp-buybar { position: fixed; left: 0; right: 0; bottom: 0; margin: 0; padding: 8px 16px calc(8px + env(safe-area-inset-bottom)); background: #fff; box-shadow: 0 -2px 12px rgba(0, 0, 0, 0.12); z-index: 30; }
   .pdp-add { min-height: 48px; }
 }
+
+/* Variantes, stock y compra (PDP-142.5). */
+.pdp-label { font-size: 12px; color: #aaa; margin: 16px 0 8px; text-transform: uppercase; }
+.pdp-swatches, .pdp-sizes { display: flex; flex-wrap: wrap; gap: 10px; }
+.pdp-swatch { width: 32px; height: 32px; border-radius: 50%; border: 2px solid #fff; box-shadow: 0 0 0 1px #ddd; cursor: pointer; padding: 0; }
+.pdp-swatch.is-active { box-shadow: 0 0 0 2px #555; }
+.pdp-size { min-width: 44px; min-height: 36px; padding: 8px 10px; border: 1px solid #e5e5e5; background: #fff; color: #aaa; cursor: pointer; font-size: 13px; }
+.pdp-size.is-active { border-color: #555; color: #333; }
+.pdp-size.is-soldout { text-decoration: line-through; }
+.pdp-stock { font-size: 13px; color: #9c9; margin: 14px 0; }
+.pdp-stock.is-out { color: #c66; }
+.pdp-add:disabled { background: #bbb; cursor: not-allowed; }
+.pdp-added { font-size: 12px; color: #9c9; margin: 8px 0 0; }
+.pdp-error { font-size: 12px; color: #c66; margin: 8px 0 0; }
